def load_current_editorial_batch_paths() -> set[str]:
    if not EDITORIAL_AUDIT_TRACKER_PATH.exists():
        return set()
    try:
        tracker = json.loads(EDITORIAL_AUDIT_TRACKER_PATH.read_text())
    except (json.JSONDecodeError, OSError):
        return set()
    return {
        str(page.get("pagePath", "")).strip()
        for page in tracker.get("currentBatch", {}).get("pages", [])
        if str(page.get("pagePath", "")).strip()
    }


CURRENT_EDITORIAL_BATCH_PATHS = load_current_editorial_batch_paths()


def is_current_editorial_batch_page(page_or_path: dict | str | None) -> bool:
    if isinstance(page_or_path, dict):
        path = page_or_path.get("built_path", "")
    else:
        path = page_or_path or ""
    return str(path).strip() in CURRENT_EDITORIAL_BATCH_PATHS


def resolve_build_date() -> date:
    override = os.environ.get("BYTESEISMIC_BUILD_DATE", "").strip()
    if not override:
        return date.today()
    try:
        return date.fromisoformat(override)
    except ValueError as exc:
        raise ValueError(
            "BYTESEISMIC_BUILD_DATE must use YYYY-MM-DD format."
        ) from exc


BUILD_DATE = resolve_build_date()
