def prompt_requests_dialogue(prompt: str) -> bool:
    lowered = clean_text(prompt).lower()
    return "dialogue" in lowered and any(
        term in lowered
        for term in ("create", "produce", "provide", "imagine", "write", "continue")
    )


def normalized_school_dialogue_key(title: str, prompt: str) -> str:
    title_key = clean_text(title).strip(" ?!.").lower()
    prompt_key = clean_text(prompt).lower()
    aliases = {
        "critical theory": "critical theorists",
        "critical theorists": "critical theorists",
        "continental philosophy": "continental philosophers",
        "continental philosophers": "continental philosophers",
        "empiricism": "empiricists",
        "empiricists": "empiricists",
        "existentialism": "existentialists",
        "existentialists": "existentialists",
        "phenomenology": "phenomenologists",
        "phenomenologists": "phenomenologists",
        "pragmatism": "pragmatists",
        "pragmatists": "pragmatists",
        "rationalism": "rationalists",
        "rationalists": "rationalists",
        "scholasticism": "scholastics",
        "scholastics": "scholastics",
    }
    if title_key == "ancient philosophers" and "asian ancient philosopher" in prompt_key:
        return "ancient philosophers"
    if "analytic philosopher" in prompt_key:
        return "analytic philosophers"
    return aliases.get(title_key, title_key)


def synthetic_teaching_dialogue_turns(page: dict, prompt: str) -> list[dict]:
    if not prompt_requests_dialogue(prompt):
        return []
    key = normalized_school_dialogue_key(page.get("title", ""), prompt)
    profile = SCHOOL_TEACHING_DIALOGUE_PROFILES.get(key)
    if not profile:
        title = topic_label(page.get("title", "the view"))
        profile = {
            "teacher": title,
            "central": f"the central pressure inside {title}",
            "contrast": "a label that sounds clear until a concrete case tests it",
            "case": "a live disagreement where the first formulation is too simple",
            "risk": "turning the topic into a summary rather than a practice of inquiry",
            "method": "state the claim, test the distinction, and let the objection clarify what is at stake",
            "objection": "that the view may clarify one pressure while hiding another",
            "payoff": "the student leaves with a question that can guide further reading",
        }
    teacher = profile["teacher"]
    return [
        {"speaker": "Student", "text": "I keep hearing this tradition named, but I only have a slogan. Where should I begin?"},
        {"speaker": teacher, "text": f"Begin with this pressure: {profile['central']}. If that pressure is invisible, the rest becomes a vocabulary lesson."},
        {"speaker": "Student", "text": "So the first task is not memorizing names, but seeing what problem makes the tradition necessary?"},
        {"speaker": teacher, "text": f"Exactly. The tradition starts to matter when it exposes {profile['contrast']}."},
        {"speaker": "Student", "text": "Can you give me a case where that difference is not just academic?"},
        {"speaker": teacher, "text": f"Take this case: {profile['case']}. The question is what becomes easier to see once the tradition is allowed to do its work."},
        {"speaker": "Student", "text": "What would an impatient reader miss in that case?"},
        {"speaker": teacher, "text": f"They would miss the method: {profile['method']}."},
        {"speaker": "Student", "text": "But couldn't that method become its own bad habit?"},
        {"speaker": teacher, "text": f"Yes. Its main danger is {profile['risk']}."},
        {"speaker": "Student", "text": "Then the tradition is not automatically right just because it notices something others miss."},
        {"speaker": teacher, "text": "Right. A serious tradition earns trust by naming both its insight and its temptation."},
        {"speaker": "Student", "text": "What is the strongest objection a beginner should keep in view?"},
        {"speaker": teacher, "text": f"The strongest objection is {profile['objection']}."},
        {"speaker": "Student", "text": "How should the tradition answer without merely repeating itself?"},
        {"speaker": teacher, "text": "It has to return to the case and show what actually changes in judgment, not just defend its favorite vocabulary."},
        {"speaker": "Student", "text": "So I should ask what the view helps me notice, what it distorts, and what would force revision?"},
        {"speaker": teacher, "text": "That is the right discipline. A useful tradition sharpens attention while remaining answerable to its own failures."},
        {"speaker": "Student", "text": "What should I leave this dialogue carrying into the next page?"},
        {"speaker": teacher, "text": f"Carry this: {profile['payoff']}."},
    ]


def synthetic_prompt_dialogue_turns(page: dict, prompt: str) -> list[dict]:
    if not prompt_requests_dialogue(prompt):
        return []
    if page.get("section_id") == "philosophers":
        philosopher = topic_label(page.get("title", ""))
        profile = philosopher_profile_for_title(page.get("title", ""))
        if profile:
            anchor = dialogue_anchor_for_prompt(prompt) or "beginner-dialogue"
            return synthetic_dialogue_turns(philosopher, profile, anchor)
    return synthetic_teaching_dialogue_turns(page, prompt)


def parse_dialogue_turn_text(raw_text: str) -> dict | None:
    lines = [
        clean_text(line)
        for line in raw_text.splitlines()
        if clean_text(line)
    ]
    if not lines:
        return None
    speaker = ""
    body = ""
    if lines[0].endswith(":") and len(lines) > 1:
        speaker = lines[0].rstrip(":").strip()
        body = clean_text(" ".join(lines[1:]))
    else:
        match = re.match(r"^([^:]{2,48}):\s+(.+)$", clean_text(raw_text), flags=re.DOTALL)
        if match:
            speaker = clean_text(match.group(1)).rstrip(":")
            body = clean_text(match.group(2))
    if not speaker or not body:
        return None
    body = collapse_duplicate_function_words(body)
    lowered_speaker = speaker.lower()
    if lowered_speaker in {"summary", "introduction", "conclusion"}:
        return None
    if len(body.split()) < 4:
        return None
    return {"speaker": speaker, "text": body}


def extract_original_dialogue_sections(content_html: str, title: str) -> dict[str, dict]:
    soup = BeautifulSoup(content_html or "", "html.parser")
    root = soup.select_one(".entry-content") or soup.select_one(".wp-block-post-content") or soup
    sections: dict[str, dict] = {}
    h2s = root.find_all("h2")
    for h2 in h2s:
        prompt = clean_text(h2.get_text(" ", strip=True))
        anchor = dialogue_anchor_for_prompt(prompt)
        if anchor not in {"beginner-dialogue", "deeper-dialogue", "critical-dialogue"}:
            continue
        heading = ""
        turns: list[dict] = []
        for sibling in h2.next_siblings:
            if isinstance(sibling, Tag) and sibling.name == "h2":
                break
            if not isinstance(sibling, Tag):
                continue
            if sibling.name in {"h3", "h4"} and not heading:
                candidate = clean_text(sibling.get_text(" ", strip=True))
                if candidate and "summary" not in candidate.lower():
                    heading = candidate
            if sibling.name == "p":
                turn = parse_dialogue_turn_text(sibling.get_text("\n", strip=True))
                if turn:
                    turns.append(turn)
            for paragraph in sibling.find_all("p"):
                turn = parse_dialogue_turn_text(paragraph.get_text("\n", strip=True))
                if turn:
                    turns.append(turn)
        deduped_turns = []
        seen = set()
        for turn in turns:
            key = (turn["speaker"].lower(), turn["text"].lower())
            if key in seen:
                continue
            seen.add(key)
            deduped_turns.append(turn)
        if deduped_turns:
            sections[anchor] = {
                "prompt": prompt,
                "heading": heading,
                "turns": deduped_turns[:18],
            }
    return sections


def synthetic_dialogue_turns(philosopher: str, profile: dict | None, anchor: str) -> list[dict]:
    if not profile:
        return [
            {"speaker": "Beginner", "text": f"If I wanted to understand {philosopher}, where should I begin?"},
            {"speaker": philosopher, "text": f"Begin where the pressure is clearest: ask what {philosopher} makes visible that ordinary common sense tends to blur."},
            {"speaker": "Interlocutor", "text": f"So the point of reading {philosopher} is not to memorize a doctrine, but to inhabit a method of questioning?"},
            {"speaker": philosopher, "text": f"Exactly. {philosopher} is not alive on the page until it changes what the reader notices, resists, or asks next."},
        ]
    concept_labels = [split_label(concept)[0] or concept for concept in profile["concepts"][:4]]
    first_concept = concept_labels[0] if concept_labels else "the central idea"
    second_concept = concept_labels[1] if len(concept_labels) > 1 else "the neighboring distinction"
    signature = clean_text(profile["signature"]).rstrip(".")
    begin_focus = compact_text(first_concept, 56)
    if anchor == "beginner-dialogue":
        return [
            {"speaker": "Beginner", "text": f"If I had to begin with your philosophy, where does {begin_focus} first become unavoidable?"},
            {"speaker": philosopher, "text": profile["begin"]},
            {"speaker": "Beginner", "text": f"I can hear the pressure, but what does {signature} force me to reconsider in ordinary thought?"}, 
            {"speaker": philosopher, "text": f"It changes the inquiry by treating this as central: {signature}. Once that is seen, the familiar question is no longer quite the same question."},
            {"speaker": "Beginner", "text": f"So {first_concept} is less a slogan than a test for where ordinary thinking goes wrong?"},
            {"speaker": philosopher, "text": f"Exactly. {first_concept} is a pressure point. It shows where ordinary explanation has become too lazy, too confident, or too small."},
            {"speaker": "Beginner", "text": f"What bad habit does your view try to break first around {first_concept}?"},
            {"speaker": philosopher, "text": f"The first habit to break is repeating {first_concept} as a label instead of letting it reorganize the problem. In this philosophy, the slogan is only the wrapper; the pressure begins when the concept starts making demands."},
        ]
    if anchor == "deeper-dialogue":
        return [
            {"speaker": "Interlocutor", "text": f"Your view seems to depend on {first_concept} and {second_concept}. Does one discipline the other, or do they rise together?"},
            {"speaker": philosopher, "text": f"They hold together through the method. {philosopher_method_sentence(profile)} The concepts are not separate ornaments; they are parts of one discipline of seeing."},
            {"speaker": "Interlocutor", "text": f"But where does the method risk turning {first_concept} into an answer for questions it cannot really settle?"},
            {"speaker": philosopher, "text": f"Be cautious where the view is asked to explain everything at once. Its strength is that it clarifies {signature}; its danger is overextension."},
            {"speaker": "Interlocutor", "text": f"So the view is strongest when it governs inquiry about {first_concept}, not when it tries to annex every problem in sight?"},
            {"speaker": philosopher, "text": f"That is close. The system matters, but its live inheritance is the discipline it trains in the reader around {first_concept}, not the fantasy that it answers everything."},
            {"speaker": "Interlocutor", "text": f"Then what would count as a serious rival to the discipline you are recommending around {signature}?"},
            {"speaker": philosopher, "text": f"A rival that can explain {signature} without losing what made the problem urgent in the first place. When a view is protected from rivals it becomes pious furniture; when it is sharpened by rivals it may still cut."},
        ]
    return [
        {"speaker": "Critic", "text": f"The strongest objection seems clear: {profile['pressure']}"},
        {"speaker": philosopher, "text": f"Good. The objection should be allowed to speak in full, because any philosophy built around {signature} that survives only by muffling its best critic has not survived much."},
        {"speaker": "Critic", "text": f"But perhaps the objection does more than qualify your view. Perhaps it shows that {signature} works only inside a protected frame."},
        {"speaker": philosopher, "text": f"Perhaps. Yet even a limited view can remain powerful if it keeps {signature} harder to ignore than it was before."},
        {"speaker": "Critic", "text": f"So the real test is not total victory, but whether later readers can reject part of the framework without losing the insight inside {first_concept}?"},
        {"speaker": philosopher, "text": f"Exactly. Rejection matters less than whether it leaves the reader with better questions, sharper distinctions, and a cleaner sense of what {signature} was trying to protect."},
        {"speaker": "Critic", "text": f"That sounds less like triumph than disciplined salvage of {first_concept}."},
        {"speaker": philosopher, "text": f"Sometimes disciplined salvage is the honest form of inheritance. A thought can keep working even when later readers refuse to kneel before {signature} as a finished system."},
    ]


def dialogue_prompt_for_anchor(page: dict, anchor: str) -> str:
    source = page.get("dialogue_sections", {}).get(anchor, {})
    if source.get("prompt"):
        return source["prompt"]
    philosopher = topic_label(page["title"])
    prompts = {
        "voice-fragment": f"Preserve whatever in {philosopher}'s voice, cadence, or method becomes thinner when reduced to neutral exposition.",
        "beginner-dialogue": f"Imagine a dialogue between {philosopher} and a bright beginner curious about the core of the view.",
        "deeper-dialogue": f"Imagine a dialogue between {philosopher} and a philosophically serious interlocutor probing the structure of the view.",
        "critical-dialogue": f"Imagine a dialogue between {philosopher} and a critic pressing on the most vulnerable points.",
        "five-notions": f"Identify several of {philosopher}'s most enduring ideas and estimate their standing today.",
    }
    return prompts[anchor]


