def heading_is_template_like(heading: str) -> bool:
    cleaned = clean_text(heading).strip()
    if not cleaned:
        return False
    return any(snippet in cleaned for snippet in HEADING_TEMPLATE_SNIPPETS)


def heading_ends_cleanly(text: str) -> bool:
    cleaned = clean_text(text).strip()
    if not cleaned:
        return False
    terminal = cleaned.rstrip("?.!")
    words = terminal.split()
    if not words:
        return False
    return words[-1].lower() not in HEADING_END_STOPWORDS


def self_standing_question_heading(text: str) -> bool:
    cleaned = clean_text(text).strip()
    lowered = cleaned.lower()
    if not cleaned.endswith("?"):
        return False
    if len(cleaned) < 15 or len(cleaned) > 108:
        return False
    blocked_starts = (
        "is this ",
        "is that ",
        "are these ",
        "are those ",
        "would that ",
        "or does ",
        "or is ",
        "or are ",
        "or can ",
        "how can i ",
        "based on this ",
        "what are some criticisms of this view",
        "what do they mean by this",
        "which is more correct",
        "right?",
        "correct?",
        "something else?",
    )
    if lowered.startswith(blocked_starts):
        return False
    if any(fragment in lowered for fragment in (" this view", " this definition", " this claim", " this report", " this prompt", " this position", " this phenomenon", "prompt:", "discussion with ", "the challenge:")):
        return False
    return True


def question_heading_score(text: str, topic: str, position: int) -> float:
    cleaned = clean_text(text).strip()
    lowered = cleaned.lower()
    topic_tokens = {
        token
        for token in re.findall(r"[a-zA-Z]{4,}", topic.lower())
        if token not in {"page", "core", "concepts", "basic", "basics", "introduction"}
    }
    text_tokens = set(re.findall(r"[a-zA-Z]{4,}", lowered))
    overlap = len(topic_tokens & text_tokens)
    score = overlap * 10.0
    score += min(len(cleaned), 96) / 100.0
    score -= position * 0.15
    if cleaned.endswith("?"):
        score += 0.75
    if lowered.startswith(("what is ", "what are ", "why is ", "why are ", "why do ", "why does ", "how is ", "how are ", "how do ", "how does ", "can ", "could ", "should ", "is ", "are ")):
        score += 0.5
    if any(fragment in lowered for fragment in (" according to most ", " in philosophy", " in public discourse", " in knowledge acquisition", " to a functioning state")):
        score += 0.4
    return score


def prompt_surface_text(prompt: str) -> str:
    cleaned = display_label(strip_number_prefix(prompt)).strip()
    cleaned = re.sub(r"^(prompt|question)\s*\d+\s*:\s*", "", cleaned, flags=re.IGNORECASE)
    cleaned = re.sub(r"\bsecnarios\b", "scenarios", cleaned, flags=re.IGNORECASE)
    cleaned = re.sub(r"\s+", " ", cleaned)
    return cleaned


def command_prompt_heading_phrase(prompt: str, topic: str) -> str:
    cleaned = prompt_surface_text(prompt).strip(" .?")
    if not cleaned:
        return topic

    replacements = [
        (r"^provide a profile of (.+?) and .+$", r"Profile of \1"),
        (r"^provide a short paragraph explaining (.+)$", r"\1"),
        (r"^provide an extensive list of (.+?) along with .+$", r"\1"),
        (r"^provide (?:\d+|one|two|three|four|five|six|seven|eight|nine|ten|several|many|a few) hypothetical scientific studies and the confounding factors.+$", "Hypothetical studies and their confounding factors"),
        (r"^provide (?:your )?own assessment of (.+?), then assess .+$", r"Assessing \1"),
        (r"^provide (?:the )?background of (.+)$", r"Background of \1"),
        (r"^do a deep dive into (.+?), augmented by other relevant sources.+$", r"The primary arguments about \1"),
        (r"^document and report (.+)$", r"\1"),
        (r"^discuss the plausibility of (.+)$", r"The plausibility of \1"),
        (r"^discuss the rise and current status of (.+)$", r"The rise and current status of \1"),
        (r"^discuss the (.+)$", r"\1"),
        (r"^comment on (.+)$", r"\1"),
        (r"^elaborate on (.+)$", r"\1"),
        (r"^list the possible causes behind (.+)$", r"The causes behind \1"),
        (r"^list the key terms in (.+)$", r"Key terms in \1"),
        (r"^list (.+)$", r"\1"),
        (r"^create a table that (.+)$", r"\1"),
        (r"^create a table of (.+)$", r"\1"),
        (r"^present a table showing (.+)$", r"\1"),
    ]
    for pattern, replacement in replacements:
        match = re.match(pattern, cleaned, flags=re.IGNORECASE)
        if not match:
            continue
        candidate = match.expand(replacement) if "\\" in replacement else replacement
        candidate = clean_text(candidate).strip(" .")
        if candidate:
            return compact_text(candidate, 88).rstrip(".")

    fallback = re.sub(
        r"^(provide|discuss|document|report|comment on|elaborate on|explain|create|present|list|outline|summarize|analyze|assess|evaluate)\s+",
        "",
        cleaned,
        flags=re.IGNORECASE,
    )
    fallback = re.sub(r"^(and|the)\s+", "", fallback, flags=re.IGNORECASE)
    fallback = clean_text(fallback).strip(" .")
    if not fallback:
        return topic
    if fallback[0].islower():
        fallback = fallback[:1].upper() + fallback[1:]
    return compact_text(fallback, 88).rstrip(".")


