def render_route_cards(routes: list[dict], prefix: str = "") -> str:
    cards = []
    for route in routes:
        start_href = internal_article_href(prefix, route["steps"][0]["path"])
        steps = "\n".join(
            f"""\
                <li>
                  <a href="{html.escape(internal_article_href(prefix, step['path']))}">{html.escape(step['title'])}</a>
                  <span>{render_inline_text(step['reason'])}</span>
                </li>"""
            for step in route["steps"]
        )
        stats = "\n".join(
            f'                  <span class="route-card__stat">{html.escape(value)}</span>'
            for value in [route.get("difficulty", ""), route.get("length", "")]
            if value
        )
        cards.append(
            textwrap.dedent(
                f"""\
                <article class="route-card" id="route-{html.escape(route['id'])}">
                  <div class="route-card__header">
                    <p class="eyebrow">{html.escape(route['audience'])}</p>
                    <div class="route-card__stats">
{stats}
                    </div>
                  </div>
                  <h3>{html.escape(route['title'])}</h3>
                  <p>{render_inline_text(route['summary'])}</p>
                  <div class="route-card__focus">
                    <div>
                      <p class="mini-label">Best if</p>
                      <p>{render_inline_text(route['best_for'])}</p>
                    </div>
                    <div>
                      <p class="mini-label">Central question</p>
                      <p>{render_inline_text(route['central_question'])}</p>
                    </div>
                    <div>
                      <p class="mini-label">By the end</p>
                      <p>{render_inline_text(route['outcome'])}</p>
                    </div>
                  </div>
                  <ol class="route-steps">
{steps}
                  </ol>
                  <div class="route-card__actions">
                    <a class="button button--ghost" href="{html.escape(start_href)}">Start route</a>
                    {f'<a class="button button--ghost" href="{html.escape(internal_article_href(prefix, route["browse_path"]))}">{html.escape(route["browse_label"])}</a>' if route.get("browse_path") and route.get("browse_label") else ''}
                  </div>
                </article>"""
            )
        )
    return "\n".join(cards)


def render_guided_route_cards(prefix: str = "") -> str:
    return render_route_cards(GUIDED_READING_PATHS, prefix)


def render_guided_route_picker(prefix: str = "") -> str:
    items = []
    for route in GUIDED_READING_PATHS:
        items.append(
            textwrap.dedent(
                f"""\
                <a class="route-picker__item" href="#route-{html.escape(route['id'])}">
                  <span class="route-picker__meta">{html.escape(route.get('difficulty', 'Route'))} / {html.escape(route.get('length', ''))}</span>
                  <strong>{html.escape(route['title'])}</strong>
                  <span>{render_inline_text(route['summary'])}</span>
                </a>"""
            )
        )
    return "\n".join(items)


def render_glossary_cards(prefix: str = "") -> str:
    cards = []
    for entry in sorted(GLOSSARY_TERMS, key=lambda item: item["term"].lower()):
        fallacy_url = logfall_url_for_phrase(entry["term"])
        term_html = (
            logfall_anchor_html(entry["term"], fallacy_url)
            if fallacy_url
            else html.escape(entry["term"])
        )
        links = "\n".join(
            f'                    <a class="text-link" href="{html.escape(internal_article_href(prefix, path))}">{html.escape(path.strip("/").split("/")[-1].replace("-", " ").title())}</a>'
            for path in entry["paths"]
        )
        tags = "".join(f"                    {tag_archive_link(tag, prefix)}" for tag in entry["tags"])
        cards.append(
            textwrap.dedent(
                f"""\
                <article class="glossary-card" id="term-{slugify(entry['term'])}">
                  <p class="eyebrow">{html.escape(entry['branch'])}</p>
                  <h3>{term_html}</h3>
                  <p>{render_inline_text(entry['definition'])}</p>
                  <div class="glossary-card__links">
{links}
                  </div>
                  <div class="tag-row">
{tags}
                  </div>
                </article>"""
            )
        )
    return "\n".join(cards)


