def philosopher_hierarchy_profile_node(node: dict) -> bool:
    title = clean_text(node.get("title", ""))
    if not title or title.startswith(("Dialoguing with ", "Charting ")):
        return False
    canonical = philosopher_base_name(title)
    return canonical in PHILOSOPHER_PROFILES and normalized_phrase(title) == normalized_phrase(canonical)


def philosopher_hierarchy_descendants(node: dict) -> list[dict]:
    profiles: list[dict] = []
    if philosopher_hierarchy_profile_node(node):
        profiles.append(node)
    for child in node.get("children", []):
        profiles.extend(philosopher_hierarchy_descendants(child))
    return profiles


def philosopher_hierarchy_subgroups(node: dict) -> list[dict]:
    child_profiles = [child for child in node.get("children", []) if philosopher_hierarchy_profile_node(child)]
    child_clusters = [
        child
        for child in node.get("children", [])
        if not philosopher_hierarchy_profile_node(child) and philosopher_hierarchy_descendants(child)
    ]
    subgroups: list[dict] = []
    if child_profiles and not child_clusters:
        subgroups.append({"title": clean_text(node.get("title", "")), "profiles": child_profiles})
    for child in child_clusters:
        subgroups.extend(philosopher_hierarchy_subgroups(child))
    return subgroups


def render_branch_guide_page(section_id: str, pages: list[dict], hierarchy_nodes: list[dict] | None = None) -> str:
    meta = SECTION_META[section_id]
    profile = branch_profile(section_id)
    prefix = "../../"
    signals_html = render_page_signals(
        [
            ("Branch", meta["name"], None),
            ("Page form", "Branch guide", None),
            ("Best for", SECTION_SIGNAL_META.get(section_id, {}).get("best_for", meta["summary"]), None),
            ("Difficulty", SECTION_SIGNAL_META.get(section_id, {}).get("difficulty", "Foundational"), None),
        ]
    )
    section_pages = sorted(
        [page for page in pages if page["section_id"] == section_id and page["built_path"] not in GROUP_PAGE_TITLES.values()],
        key=lambda item: (item["kind"] != "cluster", item["title"].lower()),
    )
    entry_pages = section_pages[:18]
    page_items = "\n".join(
        f"""\
                <li>
                  <a href="{html.escape(internal_article_href(prefix, page['built_path']))}">{html.escape(page['title'])}</a>
                  <span>{render_inline_text(feature_summary(page, meta))}</span>
                </li>"""
        for page in entry_pages
    )
    tension_items = "\n".join(f"                <li>{render_inline_text(item)}</li>" for item in profile["items"][:4])
    branch_description = f"A guided landing page for the {meta['name']} branch of Byteseismic."
    branch_head = render_seo_head(
        title=f"{meta['name']} Branch Guide",
        description=branch_description,
        path=f"/branches/{section_id}/",
        prefix=prefix,
        page_type="website",
        section=meta["name"],
        extra_json_ld=[
            collection_page_json_ld(
                title=f"{meta['name']} Branch Guide",
                description=branch_description,
                path=f"/branches/{section_id}/",
                items=[(page["title"], page["built_path"]) for page in entry_pages],
            ),
            breadcrumb_json_ld([("Home", "/"), (f"{meta['name']} Branch Guide", f"/branches/{section_id}/")]),
        ],
    )
    breadcrumbs = breadcrumb_trail_html(
        [
            ("Home", "../../index.html"),
            (meta["name"], internal_article_href(prefix, branch_guide_path(section_id))),
        ]
    )
    philosopher_families_html = ""
    entry_points_html = textwrap.dedent(
        f"""\
                  <section class="content-card">
                    <p class="eyebrow">Entry Points</p>
                    <h2>Representative pages in this branch</h2>
                    <ul class="archive-year-list branch-entry-list">
{page_items}
                    </ul>
                  </section>"""
    )
    if section_id == "philosophers" and hierarchy_nodes:
        page_lookup = {page["built_path"]: page for page in section_pages}
        school_launches_html = "\n".join(
            textwrap.dedent(
                f"""\
                <a class="route-picker__item" href="{html.escape(internal_article_href(prefix, item['path']))}">
                  <span class="route-picker__meta">{html.escape(item['meta'])}</span>
                  <strong>{html.escape(item['title'])}</strong>
                  <span>{render_inline_text(item['summary'])}</span>
                </a>"""
            )
            for item in PHILOSOPHER_BRANCH_LAUNCHES
        )
        entry_points_html = f"""

                  <section class="content-card">
                    <p class="eyebrow">Entry Points</p>
                    <h2>Enter through living routes, not a flat shelf of names.</h2>
                    <p>These routes are arranged to give the reader a coherent first encounter: a voice, a pressure, a contrast, and a reason to keep going. If you already know the sort of philosopher you want, use the school launches just below.</p>
                    <div class="feature-grid">
{render_route_cards(PHILOSOPHER_BRANCH_ENTRY_ROUTES, prefix)}
                    </div>
                    <div class="route-picker philosopher-branch-launches">
{school_launches_html}
                    </div>
                  </section>"""
        family_data_rows = []
        for family_node in hierarchy_nodes:
            family_name = clean_text(family_node.get("title", ""))
            subgroups = philosopher_hierarchy_subgroups(family_node)
            profile_count = sum(len(group["profiles"]) for group in subgroups)
            if not profile_count:
                continue
            subgroup_blocks = []
            show_subgroup_heading = not (len(subgroups) == 1 and subgroups[0]["title"] == family_name)
            for subgroup_data in subgroups:
                subgroup_name = subgroup_data["title"]
                ordered_profiles = []
                for profile_node in subgroup_data["profiles"]:
                    dialogue_path = ""
                    chart_path = ""
                    for child in profile_node.get("children", []):
                        child_title = clean_text(child.get("title", ""))
                        if child_title.startswith("Dialoguing with "):
                            dialogue_path = child.get("built_path", "")
                        elif child_title.startswith("Charting "):
                            chart_path = child.get("built_path", "")
                    ordered_profiles.append(
                        {
                            "title": clean_text(profile_node.get("title", "")),
                            "built_path": profile_node.get("built_path", ""),
                            "dialogue_path": dialogue_path,
                            "chart_path": chart_path,
                        }
                    )
                entries_html = "\n".join(
                    f"""\
                        <li class="philosopher-family__entry">
                          <div class="philosopher-family__heading">
                            <a class="philosopher-family__name" href="{html.escape(internal_article_href(prefix, entry['built_path']))}">{html.escape(entry['title'])}</a>
                            <span class="philosopher-family__meta">{render_inline_text(feature_summary(page_lookup[entry['built_path']], meta))}</span>
                          </div>
                          <div class="tag-row philosopher-family__links">
                            <a class="tag-chip" href="{html.escape(internal_article_href(prefix, entry['built_path']))}">Profile</a>
                            {f'<a class="tag-chip" href="{html.escape(internal_article_href(prefix, entry["dialogue_path"]))}">Dialogue</a>' if entry.get('dialogue_path') else ''}
                            {f'<a class="tag-chip" href="{html.escape(internal_article_href(prefix, entry["chart_path"]))}">Chart</a>' if entry.get('chart_path') else ''}
                          </div>
                        </li>"""
                    for entry in ordered_profiles
                )
                subgroup_heading_html = (
                    f'<h3 class="philosopher-family__subgroup-title">{html.escape(subgroup_name)}</h3>'
                    if show_subgroup_heading
                    else ""
                )
                subgroup_blocks.append(
                    f"""\
                      <div class="philosopher-family__subgroup">
                        {subgroup_heading_html}
                        <ul class="archive-year-list philosopher-family__list">
{entries_html}
                        </ul>
                      </div>"""
                )
            family_titles = {
                clean_text(profile_node.get("title", ""))
                for subgroup in subgroups
                for profile_node in subgroup["profiles"]
            }
            family_html = f"""\
                  <details class="tag-results__group philosopher-family__group">
                    <summary>
                      <span>{html.escape(family_name)}</span>
                      <span>{profile_count} thinker{'' if profile_count == 1 else 's'}</span>
                    </summary>
                    <div class="philosopher-family__body">
                      <p class="philosopher-family__intro">
                        Use this family view when you want the branch to feel navigable rather than merely large. Each thinker below is surfaced through the same three lanes: profile, dialogue, and chart.
                      </p>
{chr(10).join(subgroup_blocks)}
                    </div>
                  </details>"""
            family_data_rows.append(
                {
                    "name": family_name,
                    "titles": family_titles,
                    "html": family_html,
                }
            )
        filtered_family_blocks = []
        seen_title_sets: list[set[str]] = []
        for family_row in family_data_rows:
            titles = family_row["titles"]
            if any(titles < prior_titles for prior_titles in seen_title_sets):
                continue
            filtered_family_blocks.append(family_row["html"])
            seen_title_sets.append(titles)
        philosopher_families_html = f"""

                  <section class="content-card">
                    <p class="eyebrow">Philosopher Families</p>
                    <h2>Meet the newer figures through the same profile, dialogue, and chart structure.</h2>
                    <p>This makes the symmetry visible from navigation itself: readers can move by tradition, then by thinker, then by the exact supporting page form they want.</p>
                    <div class="tag-results__groups philosopher-family-groups">
{chr(10).join(filtered_family_blocks)}
                    </div>
                  </section>"""
    return textwrap.dedent(
        f"""\
        {AUTO_MARKER}
        <!DOCTYPE html>
        <html lang="en">
          <head>
            <meta charset="utf-8" />
            <meta name="viewport" content="width=device-width, initial-scale=1" />
{branch_head}
          </head>
          <body data-page-type="archive" data-current-section="{section_id}">
            <div class="page-shell">
              <header class="hero hero--article">
{render_hero_image("../../")}
                <div class="hero__content">
                  <div class="breadcrumbs">
                    {breadcrumbs}
                  </div>
                  <p class="hero__kicker">Branch Guide</p>
                  <h1>{html.escape(meta['name'])}</h1>
                  <p class="article-standfirst">{render_inline_text(meta['summary'])}</p>
{signals_html}
                </div>
              </header>

              <div class="article-layout article-layout--single">
                <main class="article-stack">
                  <section class="content-card">
                    <p class="eyebrow">Why This Branch Matters</p>
                    <h2>{html.escape(profile['standfirst'])}</h2>
                    <p>{render_inline_text(profile['stakes'])}</p>
                    <p>{render_inline_text(profile['route'])}</p>
                  </section>

                  <section class="content-card">
                    <p class="eyebrow">Core Tensions</p>
                    <h2>The branch becomes useful when these pressures stay visible.</h2>
                    <ul>
{tension_items}
                    </ul>
                  </section>
{entry_points_html}
{philosopher_families_html}
                </main>
              </div>
            </div>
          </body>
        </html>
        """
    )


def render_tag_archive_page(tag: str, tagged_pages: list[dict], tag_counts: dict[str, int]) -> str:
    prefix = "../../"
    canonical_tag = canonical_tag_key(tag) or tag
    tag_label = tag_display_label(canonical_tag)
    tag_kind = CONTROLLED_TAG_META.get(canonical_tag, {}).get("kind", "concept")
    path = tag_page_path(canonical_tag)
    matching_pages = sorted(
        [page for page in tagged_pages if canonical_tag in page.get("tags", [])],
        key=lambda page: (page["section"], page["title"]),
    )
    related_counter: Counter[str] = Counter()
    for page in matching_pages:
        related_counter.update(item for item in page.get("tags", []) if item != canonical_tag)
    related_tags = [
        item
        for item, _count in related_counter.most_common(8)
        if tag_counts.get(item, 0)
    ]
    related_html = "\n".join(
        f"                    {tag_archive_link(item, prefix)}"
        for item in related_tags
    ) or '                    <span class="muted-label">No nearby tags yet.</span>'

    section_names = dedupe(page["section"] for page in matching_pages)
    group_blocks = []
    for section_name in section_names:
        section_pages = [page for page in matching_pages if page["section"] == section_name]
        items = "\n".join(
            f"""\
                    <li>
                      <a href="{html.escape(internal_article_href(prefix, page['path']))}">{html.escape(page['title'])}</a>
                      <span>{render_inline_text(page['summary'])}</span>
                    </li>"""
            for page in section_pages
        )
        group_blocks.append(
            f"""\
                  <details class="tag-results__group" open>
                    <summary>
                      <span>{html.escape(section_name)}</span>
                      <span>{len(section_pages)}</span>
                    </summary>
                    <ul class="archive-year-list tag-results__list">
{items}
                    </ul>
                  </details>"""
        )
    groups = "\n".join(group_blocks) or '                  <p class="muted-label">No pages use this tag yet.</p>'
    count = len(matching_pages)
    kicker = {
        "branch": "Branch Tag",
        "format": "Page Format",
        "concept": "Concept Tag",
    }.get(tag_kind, "Tag Path")
    tag_scope = "Branchwide" if tag_kind == "branch" else "Cross-branch"
    tag_best_for = {
        "branch": "moving through one branch without flattening it into a list",
        "format": "finding one teaching form across several branches",
        "concept": "following one recurring concept across distant pages",
    }.get(tag_kind, "tracking a recurring path through the archive")
    signals_html = render_page_signals(
        archive_page_signal_items(
            scope=tag_scope,
            scope_href="../../index.html#tag-discovery",
            page_form=kicker,
            best_for=tag_best_for,
            difficulty="Foundational",
        )
    )
    tag_description = f"Pages tagged {tag_label} in the Byteseismic philosophy site."
    tag_head = render_seo_head(
        title=f"Tag: {tag_label}",
        description=tag_description,
        path=path,
        prefix=prefix,
        page_type="website",
        extra_json_ld=[
            collection_page_json_ld(
                title=f"Tag: {tag_label}",
                description=tag_description,
                path=path,
                items=[(page["title"], page["path"]) for page in matching_pages],
            ),
            breadcrumb_json_ld([("Home", "/"), ("Tag", "/#tag-discovery"), (f"Tag: {tag_label}", path)]),
        ],
        force_noindex=True,
    )
    breadcrumbs = breadcrumb_trail_html(
        [
            ("Home", "../../index.html"),
            ("Tag", "../../index.html#tag-discovery"),
            (tag_label, internal_article_href(prefix, path)),
        ]
    )
    return textwrap.dedent(
        f"""\
        {AUTO_MARKER}
        <!DOCTYPE html>
        <html lang="en">
          <head>
            <meta charset="utf-8" />
            <meta name="viewport" content="width=device-width, initial-scale=1" />
{tag_head}
          </head>
          <body data-page-type="archive">
            <div class="page-shell">
              <header class="hero hero--article">
{render_hero_image("../../")}
                <div class="hero__content">
                  <div class="breadcrumbs">
                    {breadcrumbs}
                  </div>
                  <p class="hero__kicker">{html.escape(kicker)}</p>
                  <h1>{html.escape(tag_label)}</h1>
                  <p class="article-standfirst">
                    {count} page{"" if count == 1 else "s"} currently use this tag. Use this path as a cross-branch way to follow recurring concepts, formats, and tensions through a stable vocabulary.
                  </p>
{signals_html}
                </div>
              </header>

              <div class="article-layout article-layout--single">
                <main class="article-stack">
                  <section class="content-card">
                    <p class="eyebrow">Tagged Pages</p>
                    <h2>Pages connected by {html.escape(tag_label)}</h2>
                    <div class="tag-results__groups">
{groups}
                    </div>
                  </section>

                  <section class="content-card">
                    <p class="eyebrow">Nearby Tags</p>
                    <h2>Related paths that often appear with this one</h2>
                    <div class="tag-row">
{related_html}
                    </div>
                  </section>
                </main>
              </div>
            </div>
          </body>
        </html>
        """
    )


def target_site_path(target: Path) -> str:
    try:
        relative = target.parent.relative_to(ROOT)
    except ValueError:
        return ""
    if str(relative) == ".":
        return "/"
    return f"/{relative.as_posix()}/"


def visible_tag_chips_by_path(targets: set[Path]) -> dict[str, list[str]]:
    by_path: dict[str, list[str]] = {}
    for target in targets:
        if not target.exists() or target.name != "index.html":
            continue
        path = target_site_path(target)
        if not path:
            continue
        soup = BeautifulSoup(target.read_text(errors="ignore"), "html.parser")
        tags = []
        for chip in soup.select(".tag-chip"):
            for count in chip.select(".tag-chip__count"):
                count.decompose()
            text = clean_text(chip.get_text(" ", strip=True))
            canonical = canonical_tag_key(text)
            if canonical:
                tags.append(canonical)
        if tags:
            by_path[path] = dedupe(tags)
    return by_path


