def build_quality_report(generated_pages: list[dict]) -> dict:
    records = []
    for page in generated_pages:
        if page["built_path"] in GROUP_PAGE_TITLES.values():
            continue
        if page.get("quality_tracked") is False:
            continue
        for section in compose_sections(page):
            quality = section.get("quality")
            if not quality:
                continue
            records.append(
                {
                    "sectionId": page["section_id"],
                    "sectionName": SECTION_META[page["section_id"]]["name"],
                    "pageTitle": page["title"],
                    "pagePath": page["built_path"],
                    "anchor": section["id"],
                    "url": f'{page["built_path"]}#{section["id"]}',
                    "prompt": section.get("prompt", ""),
                    "heading": section["heading"],
                    "bodyText": clean_text(
                        " ".join(
                            list(section.get("paragraphs", []))
                            + list(section.get("list_items", []))
                            + list(section.get("question_items", []))
                            + list(section.get("learning_items", []))
                        )
                    ),
                    "score": quality["score"],
                    "level": quality["level"],
                    "needsReview": quality["needsReview"],
                    "polishOpportunity": quality.get("polishOpportunity", False),
                    "polishReasons": quality.get("polishReasons", []),
                    "exceptionalReady": quality["exceptionalReady"],
                    "needsGapFill": quality["needsGapFill"],
                    "gapReasons": quality["gapReasons"],
                    "wordCount": quality["wordCount"],
                    "avgItemWords": quality["avgItemWords"],
                    "metrics": quality["metrics"],
                    "reasons": quality["reasons"],
                    "editorialIssues": [],
                }
            )
            records[-1]["editorialIssues"] = editorial_audit_issues(records[-1])

    by_section: dict[str, list[dict]] = defaultdict(list)
    for record in records:
        by_section[record["sectionId"]].append(record)

    summaries = []
    for section_id in SECTION_IDS:
        section_records = by_section.get(section_id, [])
        if not section_records:
            continue
        level_counts = {level: 0 for level in ("exceptional", "strong", "good", "developing", "thin")}
        for record in section_records:
            level_counts[record["level"]] += 1
        total = len(section_records)
        needs_review = sum(1 for record in section_records if record["needsReview"])
        polish_opportunity = sum(1 for record in section_records if record.get("polishOpportunity"))
        needs_gap_fill = sum(1 for record in section_records if record["needsGapFill"])
        average_score = round(sum(record["score"] for record in section_records) / total, 1)
        summaries.append(
            {
                "sectionId": section_id,
                "sectionName": SECTION_META[section_id]["name"],
                "total": total,
                "averageScore": average_score,
                "needsReview": needs_review,
                "needsReviewRate": round(needs_review / total, 3),
                "polishOpportunity": polish_opportunity,
                "polishOpportunityRate": round(polish_opportunity / total, 3),
                "needsGapFill": needs_gap_fill,
                "needsGapFillRate": round(needs_gap_fill / total, 3),
                "levels": level_counts,
                "weakest": sorted(section_records, key=lambda item: (item["score"], item["pageTitle"]))[:12],
            }
        )

    summaries.sort(key=lambda item: (-item["needsReviewRate"], -item["polishOpportunityRate"], item["averageScore"], item["sectionName"]))
    weakest = sorted(records, key=lambda item: (item["score"], item["sectionName"], item["pageTitle"]))[:150]
    polish_backlog = sorted(
        [record for record in records if record.get("polishOpportunity")],
        key=lambda item: (item["score"], item["sectionName"], item["pageTitle"]),
    )[:200]
    gap_backlog = sorted(
        [record for record in records if record["needsGapFill"]],
        key=lambda item: (item["score"], item["sectionName"], item["pageTitle"]),
    )[:200]
    total_records = len(records)
    total_needs_review = sum(1 for record in records if record["needsReview"])
    total_polish = sum(1 for record in records if record.get("polishOpportunity"))
    total_gap_fill = sum(1 for record in records if record["needsGapFill"])

    return {
        "generatedAt": BUILD_DATE.isoformat(),
        "overall": {
            "totalPromptSections": total_records,
            "averageScore": round(sum(record["score"] for record in records) / max(total_records, 1), 1),
            "needsReview": total_needs_review,
            "needsReviewRate": round(total_needs_review / max(total_records, 1), 3),
            "polishOpportunity": total_polish,
            "polishOpportunityRate": round(total_polish / max(total_records, 1), 3),
            "needsGapFill": total_gap_fill,
            "needsGapFillRate": round(total_gap_fill / max(total_records, 1), 3),
        },
        "editorialAudit": build_editorial_audit(records),
        "sectionSummaries": summaries,
        "weakest": weakest,
        "polishBacklog": polish_backlog,
        "gapBacklog": gap_backlog,
        "records": records,
    }


def editorial_audit_issues(record: dict) -> list[str]:
    heading = clean_text(record.get("heading", ""))
    prompt = clean_text(record.get("prompt", ""))
    combined = f"{heading}\n{prompt}\n{record.get('bodyText', '')}"
    issues: list[str] = []

    if re.search(r"\b(is|are) the pressure point\.$", heading, flags=re.IGNORECASE):
        issues.append("legacy pressure-point heading")
    if re.match(r"^(provide|create|list|produce|line hypothetical)\b", heading, flags=re.IGNORECASE):
        issues.append("work-order heading")
    if re.search(r"\b(the this|the the|an a|is it likely that is it|you response|to pushback on|discussion question based on)\b", combined, flags=re.IGNORECASE):
        issues.append("grammar scar")
    if re.search(r"\b(attached|uploaded|provided)\s+(?:image|images|screenshot|file|document|pdf|photo)|\bfollowing images?\b", combined, flags=re.IGNORECASE):
        issues.append("unsupported asset reference")
    if len(heading) > 128:
        issues.append("overlong heading")
    if "gives the response its center of gravity" in heading:
        issues.append("stale generated heading")
    if re.search(
        r"\b(strongest way into|distinctions keep doing work|merely sounds important|discipline judgment|gives this section its working center|question that can be tested|central pressure changes|not merely repeat the label|A good section should convert curiosity)\b",
        combined,
        flags=re.IGNORECASE,
    ):
        issues.append("semantic mush")
    if re.search(
        r"\b(becomes useful only when its standards are clear|Track how the exchange moves from|What gives this page its frame|Where the pressure naturally continues)\b",
        combined,
        flags=re.IGNORECASE,
    ):
        issues.append("stiff boilerplate")
    return dedupe(issues)


def build_editorial_audit(records: list[dict]) -> dict:
    issue_counts: dict[str, int] = defaultdict(int)
    samples: list[dict] = []
    for record in records:
        issues = record.get("editorialIssues") or editorial_audit_issues(record)
        if not issues:
            continue
        for issue in issues:
            issue_counts[issue] += 1
        if len(samples) < 40:
            samples.append(
                {
                    "url": record["url"],
                    "sectionName": record["sectionName"],
                    "pageTitle": record["pageTitle"],
                    "anchor": record["anchor"],
                    "heading": record["heading"],
                    "issues": issues,
                }
            )

    return {
        "totalIssues": sum(issue_counts.values()),
        "affectedSections": len(samples),
        "issueCounts": dict(sorted(issue_counts.items())),
        "samples": samples,
    }


def render_quality_review_page(report: dict) -> str:
    summary = report["overall"]
    editorial_audit = report.get("editorialAudit", {})
    quality_head = render_seo_head(
        title="Quality Review | Byteseismic Reconstruction",
        description="A quality ledger for tracking reconstructed prompt-response sections that need later hand refinement.",
        path="/quality-review/",
        prefix="../",
        page_type="website",
        force_noindex=True,
    )
    breadcrumbs = breadcrumb_trail_html(
        [
            ("Home", "../index.html"),
            ("Quality Review", "../quality-review/"),
        ]
    )
    signals_html = render_page_signals(
        archive_page_signal_items(
            scope="Internal",
            scope_href="../index.html",
            page_form="Editorial ledger",
            best_for="seeing the backlog, weak spots, and gap-fill queue at a glance",
            difficulty="Intermediate",
        )
    )
    issue_counts = editorial_audit.get("issueCounts", {})
    if issue_counts:
        issue_items = "\n".join(
            f"                <li><strong>{html.escape(issue)}:</strong> {count}</li>"
            for issue, count in issue_counts.items()
        )
        editorial_audit_body = (
            f"<p>The strict editorial audit is still finding <strong>{editorial_audit.get('totalIssues', 0)}</strong> pattern issue(s). "
            "These are the places to inspect before calling a branch finished.</p>\n"
            f"              <ul>\n{issue_items}\n              </ul>"
        )
    else:
        editorial_audit_body = (
            "<p>The strict editorial audit currently finds <strong>0</strong> stale headings, grammar scars, or unsupported asset references. "
            "This does not mean the archive is finished; it means the obvious gremlins have stopped waving from the balcony.</p>"
        )
    section_blocks = []
    for branch in report["sectionSummaries"]:
        weak_items = "\n".join(
            f'                <li><a href="..{html.escape(item["url"])}">{html.escape(item["pageTitle"])} — {html.escape(item["anchor"])}</a><span>{html.escape(item["level"])} · {item["score"]}</span></li>'
            for item in branch["weakest"][:10]
        )
        section_blocks.append(
            f"""\
            <section class="article-section">
              <p class="eyebrow">Quality Branch</p>
              <h2>{html.escape(branch["sectionName"])}</h2>
              <p>
                Average score: <strong>{branch["averageScore"]}</strong>. Sections needing review:
                <strong>{branch["needsReview"]}</strong> of <strong>{branch["total"]}</strong>.
                Polish queue: <strong>{branch["polishOpportunity"]}</strong>.
                Gap-fill backlog: <strong>{branch["needsGapFill"]}</strong>.
                Levels: exceptional {branch["levels"]["exceptional"]}, strong {branch["levels"]["strong"]}, good {branch["levels"]["good"]},
                developing {branch["levels"]["developing"]}, thin {branch["levels"]["thin"]}.
              </p>
              <ul class="archive-year-list">
{weak_items}
              </ul>
            </section>"""
        )

    weakest_items = "\n".join(
        f'                <li><a href="..{html.escape(item["url"])}">{html.escape(item["sectionName"])} / {html.escape(item["pageTitle"])} / {html.escape(item["anchor"])}</a><span>{html.escape(item["level"])} · {item["score"]}</span></li>'
        for item in report["weakest"][:30]
    )
    gap_items = "\n".join(
        f'                <li><a href="..{html.escape(item["url"])}">{html.escape(item["sectionName"])} / {html.escape(item["pageTitle"])} / {html.escape(item["anchor"])}</a><span>{html.escape("; ".join(item["gapReasons"]) or "needs hand detail")}</span></li>'
        for item in report["gapBacklog"][:35]
    )
    polish_items = "\n".join(
        f'                <li><a href="..{html.escape(item["url"])}">{html.escape(item["sectionName"])} / {html.escape(item["pageTitle"])} / {html.escape(item["anchor"])}</a><span>{html.escape("; ".join(item.get("polishReasons", [])) or "ready for a calmer, more deliberate editorial pass")}</span></li>'
        for item in report.get("polishBacklog", [])[:35]
    )

    return textwrap.dedent(
        f"""\
        {AUTO_MARKER}
        <!DOCTYPE html>
        <html lang="en">
          <head>
            <meta charset="utf-8" />
            <meta name="viewport" content="width=device-width, initial-scale=1" />
{quality_head}
          </head>
          <body data-page-type="archive">
            <div class="page-shell">
              <header class="hero hero--article">
{render_hero_image("../")}
                <div class="hero__content">
                  <div class="breadcrumbs">
                    {breadcrumbs}
                  </div>
                  <p class="hero__kicker">Internal Ledger</p>
                  <h1>Quality Review</h1>
                  <p class="article-standfirst">
                    A working ledger for separating repair-level issues from relative polish targets
                    inside an already mature reconstruction.
                  </p>
{signals_html}
                </div>
              </header>

              <div class="article-layout article-layout--single">
                <main class="article-stack">
                  <section class="content-card">
                    <p class="eyebrow">Quality Scope</p>
                    <h2>Prompt-response coverage</h2>
                    <p>
                      This review tracks <strong>{summary["totalPromptSections"]}</strong> generated
                      prompt-response sections. Average score is <strong>{summary["averageScore"]}</strong>.
                      Sections needing review: <strong>{summary["needsReview"]}</strong>
                      ({round(summary["needsReviewRate"] * 100, 1)}%).
                      Polish queue: <strong>{summary.get("polishOpportunity", 0)}</strong>
                      ({round(summary.get("polishOpportunityRate", 0) * 100, 1)}%).
                      Gap-fill backlog: <strong>{summary["needsGapFill"]}</strong>
                      ({round(summary["needsGapFillRate"] * 100, 1)}%).
                    </p>
                    <p>
                      Levels are heuristic, not final judgment: <strong>exceptional</strong>,
                      <strong>strong</strong>,
                      <strong>good</strong>, <strong>developing</strong>, and <strong>thin</strong>.
                      “Developing” and “thin” are the repair backlog. “Strong” means publishable.
                      The polish queue is for sections that work but could still become clearer, richer,
                      or more teachable. The gap-fill column is narrower: it points to real missing
                      texture such as quotations, examples, objections, or historical pressure.
                    </p>
                    <p>
                      The “weakest” list is relative, not accusatory. It shows where the archive is
                      least exceptional, not where it is broken. Think of it as a polishing queue,
                      not a naughty chair.
                    </p>
                  </section>

                  <section class="content-card">
                    <p class="eyebrow">Editorial Audit</p>
                    <h2>Scrutiny pass</h2>
                    {editorial_audit_body}
                  </section>

                  <section class="gap-note">
                    <p class="eyebrow">Philosophers Gap-Fill</p>
                    <h2>Canon needs encounter, not nameplates</h2>
                    <p>
                      The Philosophers branch is intentionally marked for future enrichment. The next
                      exceptional pass should add primary-source fragments, historical settings,
                      signature problems, influence trails, and objections that let each thinker
                      speak with a recognizable philosophical temperature. Otherwise we risk producing
                      a very elegant hall of portraits, which is lovely, but portraits rarely argue back.
                    </p>
                  </section>

                  <section class="article-section">
                    <p class="eyebrow">Polish Queue</p>
                    <h2>Strong pages that can still become cleaner and sharper</h2>
                    <p>
                      These sections are not repair work. They already function. They simply still have
                      room for stronger examples, calmer sequencing, or a better objection-and-reply rhythm.
                    </p>
                    <ul class="archive-year-list">
{polish_items}
                    </ul>
                  </section>

                  <section class="article-section">
                    <p class="eyebrow">Exceptional Backlog</p>
                    <h2>Good enough is not the ceiling</h2>
                    <ul class="archive-year-list">
{gap_items}
                    </ul>
                  </section>

                  <section class="article-section">
                    <p class="eyebrow">Relative Queue</p>
                    <h2>Relative polish queue</h2>
                    <p>
                      These are the lowest-scoring sections by comparison with the rest of the archive.
                      They may still be strong and publishable; they simply have the most room to move
                      from solid reconstruction toward exceptional hand-curated explanation.
                    </p>
                    <ul class="archive-year-list">
{weakest_items}
                    </ul>
                  </section>

                  <div class="article-body">
        {'\n\n'.join(section_blocks)}
                  </div>
                </main>
              </div>
            </div>
          </body>
        </html>
        """
    )


def render_quality_markdown(report: dict) -> str:
    lines = [
        "# Byteseismic Quality Ledger",
        "",
        f"Generated: {report.get('generatedAt', BUILD_DATE.isoformat())}",
        "",
        f"Tracked prompt-response sections: {report['overall']['totalPromptSections']}",
        f"Average score: {report['overall']['averageScore']}",
        f"Needs review: {report['overall']['needsReview']} ({round(report['overall']['needsReviewRate'] * 100, 1)}%)",
        f"Polish queue: {report['overall'].get('polishOpportunity', 0)} ({round(report['overall'].get('polishOpportunityRate', 0) * 100, 1)}%)",
        f"Gap-fill backlog: {report['overall']['needsGapFill']} ({round(report['overall']['needsGapFillRate'] * 100, 1)}%)",
        "",
        "## Editorial Audit",
        "",
        f"Pattern issues found: {report.get('editorialAudit', {}).get('totalIssues', 0)}",
        "",
    ]
    issue_counts = report.get("editorialAudit", {}).get("issueCounts", {})
    if issue_counts:
        for issue, count in issue_counts.items():
            lines.append(f"- {issue}: {count}")
        lines.append("")

    lines.extend([
        "## Branch Summary",
        "",
        "| Branch | Avg | Needs Review | Gap Fill | Exceptional | Strong | Good | Developing | Thin |",
        "| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |",
    ])
    for branch in report["sectionSummaries"]:
        levels = branch["levels"]
        lines.append(
            f"| {branch['sectionName']} | {branch['averageScore']} | {branch['needsReview']}/{branch['total']} | {branch['needsGapFill']}/{branch['total']} | {levels['exceptional']} | {levels['strong']} | {levels['good']} | {levels['developing']} | {levels['thin']} |"
        )

    lines.extend(["", "## Polish Queue", ""])
    for item in report.get("polishBacklog", [])[:150]:
        reasons = "; ".join(item.get("polishReasons", [])) or "ready for a calmer, sharper editorial pass"
        lines.append(
            f"- `{item['level']}` {item['score']} [{item['sectionName']} / {item['pageTitle']}#{item['anchor']}](..{item['url']}): {reasons}"
        )

    lines.extend(["", "## Exceptional Gap-Fill Backlog", ""])
    for item in report["gapBacklog"][:150]:
        reasons = "; ".join(item["gapReasons"]) or "needs hand detail"
        lines.append(
            f"- `{item['level']}` {item['score']} [{item['sectionName']} / {item['pageTitle']}#{item['anchor']}](..{item['url']}): {reasons}"
        )

    lines.extend([
        "",
        "## Relative Polish Queue",
        "",
        "These are the lowest-scoring sections relative to the rest of the archive. Strong entries are publishable; this list is a polishing queue, not a failure list.",
        "",
    ])
    for item in report["weakest"][:150]:
        reasons = "; ".join(item["reasons"])
        lines.append(
            f"- `{item['level']}` {item['score']} [{item['sectionName']} / {item['pageTitle']}#{item['anchor']}](..{item['url']}): {reasons}"
        )

    lines.append("")
    return "\n".join(lines)


def write_quality_files(report: dict) -> None:
    quality_dir = ROOT / "quality"
    quality_dir.mkdir(exist_ok=True)
    (quality_dir / "section-quality.json").write_text(json.dumps(report, indent=2, ensure_ascii=False))
    (quality_dir / "section-quality.md").write_text(render_quality_markdown(report))


def write_if_allowed(target: Path, contents: str) -> bool:
    if target.exists():
        existing = target.read_text()
        if AUTO_MARKER not in existing:
            return False
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(contents)
    return True


def render_dialectical_turn_html(page: dict) -> str:
    section = stance_change_section(page)
    if not section:
        return ""
    return textwrap.dedent(
        f"""\
          <section class="article-section" id="dialectical-turn">
            <div class="article-section__meta">
              <p class="eyebrow">{html.escape(section["eyebrow"])}</p>
            </div>
            <h2>{html.escape(section["heading"])}</h2>
            {render_paragraphs(section.get("paragraphs", []))}
            {render_list_section(section.get("list_items", []))}
            {render_learning_card(section.get("learning_items", []))}
          </section>"""
    )


def inject_dialectical_turn_into_manual_page(target: Path, page: dict) -> bool:
    if not target.exists():
        return False
    existing = target.read_text()
    if AUTO_MARKER in existing or 'data-page-type="article"' not in existing:
        return False

    turn_html = render_dialectical_turn_html(page)
    if not turn_html:
        return False

    cleaned = DIALECTICAL_SECTION_RE.sub("\n", existing)
    markers = [
        r"\n\s*<section\b(?=[^>]*\bclass=\"article-section quiz-section\")(?=[^>]*\bdata-quiz\b)",
        r"\n\s*<section class=\"article-section\" id=\"synthesis\">",
        r"\n\s*<section class=\"article-section\" id=\"future-branches\">",
        r"\n\s*<section class=\"article-outline-slot\"",
        r"\n\s*<section class=\"process-note\"",
        r"\n\s*</main>",
    ]
    insert_at = -1
    for marker in markers:
        match = re.search(marker, cleaned)
        if match:
            insert_at = match.start()
            break
    if insert_at == -1:
        return False

    updated = f"{cleaned[:insert_at].rstrip()}\n\n{turn_html}\n{cleaned[insert_at:].lstrip()}"
    if updated == existing:
        return False
    target.write_text(updated)
    return True


